sysdrills/01-estimation/02-peak-qps.solution:
export function peakQps(dailyRequests, peakFactor) {
  return (dailyRequests * peakFactor) / 86_400;
}

export function requestsInPeakHour(dailyRequests, peakFactor) {
  return peakQps(dailyRequests, peakFactor) * 3_600;
}

