sysdrills/01-estimation/03-storage-growt.solution:
const BYTES_PER_GB = 1_000_000_000;

export function bytesPerDay(writesPerDay, bytesPerWrite) {
  return writesPerDay * bytesPerWrite;
}

export function gbPerYear(writesPerDay, bytesPerWrite) {
  return Math.ceil((bytesPerDay(writesPerDay, bytesPerWrite) * 365) / BYTES_PER_GB);
}

