sysdrills/01-estimation/05-cache-working.solution:
export function workingSetBytes(objects, hotPermille, objectBytes) {
  return (objects * hotPermille * objectBytes) / 1000;
}

export function nodesNeeded(objects, hotPermille, objectBytes, nodeBytes) {
  return Math.ceil(workingSetBytes(objects, hotPermille, objectBytes) / nodeBytes);
}

