sysdrills/01-estimation/06-cost-per-mont.solution:
export const HOURS_PER_MONTH = 730;

export function monthlyCostCents(instances, centsPerHour) {
  return instances * centsPerHour * HOURS_PER_MONTH;
}

export function instancesWithinBudget(budgetCents, centsPerHour) {
  return Math.floor(budgetCents / monthlyCostCents(1, centsPerHour));
}

